-- Tags: no-fasttest
-- no-fasttest: requires the ORC input format, which is not built in fasttest.

SET allow_experimental_variant_type = 1;

-- union<struct<a:tinyint>, string> with a null struct payload, read with an explicit schema whose
-- Tuple field needs a value-checking cast (Int8 -> Enum8). The null-struct row becomes a Variant
-- NULL, so its placeholder tuple field must not be validated by the branch-repair cast. Rows:
-- (a=1), NULL (null struct payload), 'text', (a=1), NULL (null string payload).
SELECT u FROM format(ORC, $$u Variant(Tuple(a Enum8('x' = 1)), String)$$, unhex('')) ORDER BY toString(u);

-- The same file read as Tuple(a Int8): the tuple field is still Nullable(Int8) internally, so the
-- null-payload row must not turn the field cast into a NULL-to-non-Nullable failure either.
SELECT u FROM format(ORC, $$u Variant(Tuple(a Int8), String)$$, unhex('')) ORDER BY toString(u);

-- Inferred schema: the struct field is recursively made Nullable, and the null-struct payload is
-- a Variant NULL.
SELECT toTypeName(u) FROM format(ORC, unhex('')) LIMIT 1;
SELECT u FROM format(ORC, unhex('')) ORDER BY toString(u);

-- Every struct-tagged row has a null struct payload: the branch has no valid row to cast, so the
-- repair falls back to a default-valued column of the target type (never read). Rows: NULL, NULL, 'only'.
SELECT u FROM format(ORC, $$u Variant(Tuple(a Enum8('x' = 1)), String)$$, unhex('')) ORDER BY toString(u);
